-- =============================================================================
-- Import live backoffice snapshot (data only)
-- =============================================================================
-- v1 applied this BEFORE auth.users FKs on updated_by existed; a later migration
-- nulled orphan FKs then VALIDATEd constraints. With the squashed baseline those
-- FKs already exist, so drop them for the load, clean orphans, then recreate.
-- End-state matches v1 after 20260611124334 cleanup.
-- =============================================================================

ALTER TABLE backoffice.product_login_methods DROP CONSTRAINT IF EXISTS bo_product_login_methods_updated_by_fkey;
ALTER TABLE backoffice.product_documents DROP CONSTRAINT IF EXISTS bo_product_documents_updated_by_fkey;
ALTER TABLE backoffice.product_documents DROP CONSTRAINT IF EXISTS bo_product_documents_created_by_fkey;
ALTER TABLE backoffice.product_document_versions DROP CONSTRAINT IF EXISTS bo_product_document_versions_author_id_fkey;

/*
  =============================================================================
  BOLT PLATFORM - IMPORT LIVE BACKOFFICE DATA
  =============================================================================
  Source:   manual export from live Supabase (2026-06-10)
  Prereqs:  20260609000001_full_schema.sql, 20260609000002_seed_tenants.sql
  Scope:    5 production products (excludes it-winfinity, xc-winfinity)
  =============================================================================
*/

BEGIN;
ALTER TABLE backoffice.product_branding DISABLE TRIGGER product_branding_bump_version;
ALTER TABLE backoffice.product_public_config DISABLE TRIGGER product_public_config_bump_version;
ALTER TABLE backoffice.product_translations DISABLE TRIGGER product_translations_bump_version;
-- ===========================================================================
-- bo_services
-- ===========================================================================

ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  display_name = EXCLUDED.display_name,
  description = EXCLUDED.description,
  status = EXCLUDED.status,
  global_product_id = EXCLUDED.global_product_id,
  created_at = EXCLUDED.created_at,
  updated_at = EXCLUDED.updated_at;
-- ===========================================================================
-- bo_products
-- ===========================================================================

ON CONFLICT (id) DO UPDATE SET
  service_id = EXCLUDED.service_id,
  slug = EXCLUDED.slug,
