-- ===========================================================================
-- bo_product_menu_items
-- ===========================================================================

-- edge: these rows carry the link in route (url empty). normalize_menu_item_link would derive route
-- from the empty url and clear it: insert with the trigger off, then move the link into url.
ALTER TABLE backoffice.product_menu_items DISABLE TRIGGER product_menu_items_normalize_link;
-- edge: no (product_locale_id, environment, item_key) unique index (an item_key can repeat across menus)
ON CONFLICT (id) DO UPDATE SET
  label = EXCLUDED.label,
  url = EXCLUDED.url,
  icon = EXCLUDED.icon,
  display_order = EXCLUDED.display_order,
  parent_key = EXCLUDED.parent_key,
  visible = EXCLUDED.visible,
  created_at = EXCLUDED.created_at,
  updated_at = EXCLUDED.updated_at,
  label_i18n_key = EXCLUDED.label_i18n_key,
  route = EXCLUDED.route,
  external_url = EXCLUDED.external_url,
  auth_required = EXCLUDED.auth_required,
  min_app_version = EXCLUDED.min_app_version,
  max_app_version = EXCLUDED.max_app_version,
  feature_flag = EXCLUDED.feature_flag,
  badge_text = EXCLUDED.badge_text,
  badge_color = EXCLUDED.badge_color,
  icon_url = EXCLUDED.icon_url;
UPDATE backoffice.product_menu_items
SET url = route
WHERE url = '' AND COALESCE(route, '') <> '';
ALTER TABLE backoffice.product_menu_items ENABLE TRIGGER product_menu_items_normalize_link;
-- ===========================================================================
